export const pmTextFor = (locale: string | undefined): PmText => locale?.startsWith('en') ? pmTextEn : pmTextFr;

'use client';

import { useEffect, useMemo, useState } from 'react';
import { useRemoteChat } from '@hachej/boring-ui-kit/chat-react';
import { connectRevisionProvider } from '@hachej/boring-files/revision';
import type { RevisionProvider } from '@hachej/boring-files/revision';
import type { PmReadArtifact } from './pm-mockups';
import type { ChatIdentity } from '@hachej/boring-ui-kit/native-chat';
import type { ImproveSpec, PmTranscript } from './use-pm-panel';
import { useHostTasks } from './pm-task-source';
import { pmTextFor } from './pm-text';

/**
 * The one line an app writes: `improve: { agent: 'pm' }`. The kit opens that agent's conversation through the app's own door
 * (hachej/boring-factory#854), same origin and as the signed-in person: `GET {base}/agent` (identity), `{base}/conversations`
 * (the viewer's latest, created when there is none) and `{base}/chat?conversation=` (the native chat wire). Dictation is the host's, not
 * the agent's: `POST api/host/transcribe?language=` (audio body, answers `{ text, segments? }`). The viewer's requests are the host's task
 * API, `_tasks/api` (see `pm-task-source.tsx`; a 404 or 403 is « unavailable for now », read again later). The files the PM presents
 * (`present`) are read through the door's revision route, `{base}/resources` (`connectRevisionProvider`, on the first mockup shown).
 * Every path is relative to the page, like the app's own `api()` calls: the host may serve the app under a prefix (`/apps/<app>/`,
 * `/preview/<sha>/`).
 */
export interface ImproveAgent {
  readonly agent: string;
  /** Default `api/{agent}`, relative to the page; resolved against `document.baseURI` (so `/api/pm` stays at the origin's root). */
  readonly base?: string;
}
export type ImproveProp = ImproveSpec | ImproveAgent;
export const isImproveAgent = (value: ImproveProp | undefined): value is ImproveAgent => !!value && 'agent' in value && typeof value.agent === 'string' && !('controller' in value);

/** A path of the app, resolved like the app's own requests: against the page (`document.baseURI`), never the origin's root. */
const appUrl = (path: string) => new URL(path, document.baseURI).href;

type Door = { readonly identity: ChatIdentity; readonly conversationId: string } | { readonly error: string };
const sameOrigin = (request: Request) => fetch(new Request(request, { credentials: 'same-origin' }));

async function openDoor(path: string, signal: AbortSignal): Promise<Door> {
  const json = async (response: Response) => { if (!response.ok) throw new Error(`${response.status} ${response.statusText}`); return response.json() as Promise<Record<string, unknown>>; };
  const base = appUrl(path);
  const descriptor = await json(await fetch(`${base}/agent`, { credentials: 'same-origin', signal }));
  const identity = (descriptor['identity'] ?? descriptor) as ChatIdentity;
  if (typeof identity?.runtimeId !== 'string' || typeof identity.scopeId !== 'string' || typeof identity.principalId !== 'string') throw new Error('The agent door returned no chat identity');
  const listed = await json(await fetch(`${base}/conversations`, { credentials: 'same-origin', signal }));
  const rows = (Array.isArray(listed['conversations']) ? listed['conversations'] : []) as { readonly id: string | number; readonly archived?: boolean; readonly updatedAt?: number }[];
  const latest = rows.filter(row => !row.archived).sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0))[0];
  if (latest) return { identity, conversationId: String(latest.id) };
  const created = await json(await fetch(`${base}/conversations?op=create`, { method: 'POST', credentials: 'same-origin', headers: { 'content-type': 'application/json' }, body: '{}', signal }));
  return { identity, conversationId: String(created['conversationId']) };
}

/** Resolves `{ agent }` once `active` (the first open), then keeps the controller. `undefined` while connecting or offline (`problem`). */
export function useImproveAgent(value: ImproveProp | undefined, active: boolean, defaults: { readonly appName?: string; readonly locale?: string }): { readonly spec: ImproveSpec | undefined; readonly problem: string | undefined } {
  const agent = isImproveAgent(value) ? value : undefined;
  const base = agent ? agent.base ?? `api/${encodeURIComponent(agent.agent)}` : undefined;
  const [door, setDoor] = useState<{ readonly base: string; readonly door: Door }>();
  const [requested, setRequested] = useState(false);
  if (active && agent && !requested) setRequested(true);
  useEffect(() => {
    if (!base || !requested) return;
    const abort = new AbortController();
    openDoor(base, abort.signal).then(result => setDoor({ base, door: result }), (error: unknown) => { if (!abort.signal.aborted) setDoor({ base, door: { error: error instanceof Error ? error.message : String(error) } }); });
    return () => abort.abort();
  }, [base, requested]);
  const open = door && door.base === base && 'identity' in door.door ? door.door : undefined;
  const remote = useRemoteChat({ conversationId: open?.conversationId, endpoint: id => new URL(`${appUrl(base ?? '')}/chat?conversation=${encodeURIComponent(String(id))}`), fetch: sameOrigin, identity: open?.identity });
  const ready = remote.status === 'ready' ? remote : undefined;
  const opened = Boolean(open);
  const readArtifact = useMemo<PmReadArtifact | undefined>(() => {
    if (!base || !opened) return undefined;
    let provider: Promise<RevisionProvider> | undefined;
    return async (artifact, signal) => {
      const connecting = provider ??= connectRevisionProvider({ endpoint: appUrl(`${base}/resources`), fetch: sameOrigin });
      try {
        const read = await (await connecting).read({ target: artifact.target, revision: { kind: 'exact', value: artifact.revision } }, signal);
        return read.kind === 'available' ? new TextDecoder().decode(read.snapshot.bytes) : undefined;
      } catch (error) { if (provider === connecting) provider = undefined; throw error; }
    };
  }, [base, opened]);
  const tasks = useHostTasks(open ? appUrl('_tasks/api') : undefined, open?.identity.principalId, ready?.controller, pmTextFor(defaults.locale));
  const spec = useMemo<ImproveSpec | undefined>(() => !agent ? value as ImproveSpec | undefined : ready ? {
    controller: ready.controller, ...(defaults.appName ? { appName: defaults.appName } : {}), ...(tasks ? { tasks } : {}), ...(readArtifact ? { readArtifact } : {}),
    chatProps: { actions: ready.actions, showHistory: false, ...(defaults.locale ? { locale: defaults.locale as 'fr' } : {}) },
    pointVoice: { transcribe: async (audio: Blob, signal: AbortSignal): Promise<string | PmTranscript> => {
      const response = await fetch(appUrl(`api/host/transcribe${defaults.locale ? `?language=${encodeURIComponent(defaults.locale)}` : ''}`), { method: 'POST', credentials: 'same-origin', headers: { 'content-type': audio.type || 'application/octet-stream' }, body: audio, signal });
      if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
      const result = await response.json() as PmTranscript | { readonly text?: string };
      return typeof result.text === 'string' ? result as PmTranscript : '';
    } },
  } : undefined, [agent, value, ready, tasks, readArtifact, defaults.appName, defaults.locale]);
  const problem = door && 'error' in door.door ? door.door.error : remote.status === 'offline' ? remote.error : undefined;
  return { spec, problem };
}

'use client';

import { useMemo, useState, useSyncExternalStore } from 'react';
import type { ConversationView, EntryRecord } from '@earendil-works/pi-durable';
import { CheckIcon } from 'lucide-react';
import type { NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { Spinner } from '@/components/ui/spinner';
import { Trace, TraceCollapsible, TraceCollapsibleContent, TraceCollapsibleTrigger, TraceIcon, TraceLine, TraceTitle } from '@/components/ui/trace';
import type { PmText } from './pm-text';

/** One line of the app panel's step list: a tool the PM ran, in plain words. A failed or unfinished step is `stopped` (a neutral dot). */
export interface PmStep { readonly key: string; readonly label: string; readonly status: 'running' | 'done' | 'stopped' }
export interface PmTurnSteps {
  readonly steps: readonly PmStep[];
  /** The turn is the conversation's last and its run is still going. */
  readonly running: boolean;
  /** Reply text came after the last step: the list folds to its summary. */
  readonly replied: boolean;
}

/** The line of a tool: its own name in the map, then its `prefix_*` family, then `stepUnknown`. Never the raw name. */
export function stepLabel(name: string, text: PmText): string {
  const family = name.includes('_') ? `${name.slice(0, name.indexOf('_'))}_*` : undefined;
  return (Object.hasOwn(text.steps, name) ? text.steps[name] : family && Object.hasOwn(text.steps, family) ? text.steps[family] : undefined) ?? text.stepUnknown;
}

type Part = { readonly type?: unknown; readonly text?: unknown; readonly id?: unknown; readonly name?: unknown };
const record = (value: unknown) => value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : undefined;

/**
 * The steps of the turn the user entry `turn` starts, up to the next user message: the tool calls of its committed rounds and of the live
 * generation (when it is the last turn), matched with their results. Read from the native view only; the chat's own rows are untouched.
 */
export function turnSteps(view: Pick<ConversationView, 'entries' | 'docs'> | undefined, turn: EntryRecord['id'], text: PmText): PmTurnSteps {
  const entries = view?.entries ?? [];
  const at = entries.findIndex(entry => entry.id === turn);
  if (at < 0) return { steps: [], running: false, replied: false };
  let end = entries.findIndex((entry, index) => index > at && entry.model?.some(message => message.role === 'user'));
  if (end < 0) end = entries.length;
  const live = record(view?.docs['pi.live']);
  const running = end === entries.length && Boolean(live?.['run']);
  const calls: { readonly id: string; readonly name: string }[] = [], results = new Map<string, boolean>();
  let textAfter = false;
  const read = (content: readonly Part[]) => {
    for (const part of content) {
      if (part.type === 'toolCall' && typeof part.id === 'string' && typeof part.name === 'string') { calls.push({ id: part.id, name: part.name }); textAfter = false; }
      else if (part.type === 'text' && typeof part.text === 'string' && part.text.trim()) textAfter = true;
    }
  };
  for (const entry of entries.slice(at + 1, end)) for (const message of entry.model ?? []) {
    if (message.role === 'assistant') read(message.content as readonly Part[]);
    else if (message.role === 'toolResult') results.set(message.toolCallId, message.isError);
  }
  const generation = record(record(live?.['generation'])?.['message']);
  if (running && Array.isArray(generation?.['content'])) read(generation['content'] as readonly Part[]);
  const steps = calls.map((call, index): PmStep => {
    const failed = results.get(call.id);
    return { key: `${index}:${call.id}`, label: stepLabel(call.name, text), status: failed === undefined ? running ? 'running' : 'stopped' : failed ? 'stopped' : 'done' };
  });
  return { steps, running, replied: textAfter };
}

/**
 * The app panel's calm step list for one turn (C7, decided 2026-10-29): muted 13px lines, a spinner, a check or a neutral dot, no arguments,
 * results or errors. Open while the PM works, folded to « n étapes ▸ » once the reply arrives or the run ends; a tap opens or folds it.
 * Before the first step of a running turn it is the one « Préparation… » line.
 */
export function PmSteps({ controller, turn, text }: { readonly controller: NativeChatController; readonly turn: EntryRecord['id']; readonly text: PmText }) {
  const view = useSyncExternalStore(controller.subscribe, () => controller.getSnapshot().view, () => controller.getSnapshot().view);
  const { steps, running, replied } = useMemo(() => turnSteps(view, turn, text), [view, turn, text]);
  const [chosen, setChosen] = useState<boolean>();
  if (!steps.length) return running ? <p role="status" data-testid="pm-preparing" className="m-0 flex min-h-6 items-center gap-2 text-[13px] text-muted-foreground"><Spinner className="size-3.5" aria-hidden="true" />{text.preparing}</p> : null;
  const open = chosen ?? (running && !replied);
  return <Trace data-testid="pm-steps" data-state={running ? 'running' : 'done'} data-open={open ? 'true' : 'false'} className="gap-0">
    <TraceCollapsible open={open} onOpenChange={setChosen}>
      <TraceCollapsibleTrigger data-testid="pm-steps-summary" className="min-h-11 text-[13px]">
        <TraceLine className="text-[13px]"><TraceTitle>{text.stepsSummary(steps.length)}</TraceTitle></TraceLine>
      </TraceCollapsibleTrigger>
      <TraceCollapsibleContent className="mt-0 flex flex-col gap-1">
        {steps.map(step => <TraceLine key={step.key} data-testid="pm-step" data-step-status={step.status} className="min-h-6 text-[13px]">
          <TraceIcon>{step.status === 'running' ? <Spinner className="size-3.5" /> : step.status === 'done' ? <CheckIcon className="size-3.5" /> : <span data-testid="pm-step-dot" className="size-1.5 rounded-full bg-muted-foreground/60" />}</TraceIcon>
          <TraceTitle>{step.label}</TraceTitle>
        </TraceLine>)}
      </TraceCollapsibleContent>
    </TraceCollapsible>
  </Trace>;
}

'use client';

import { createContext, useContext, useEffect, useMemo, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { ChevronRightIcon } from 'lucide-react';
import type { ArtifactDescriptor, PresentedArtifact } from '@hachej/boring-ui-kit/chat-view';
import { artifactVersionKey, recogniseArtifact } from '@hachej/boring-ui-kit/chat-view';
import { Button } from '@/components/ui/button';
import { InteractiveFrame } from '../viewer-frame/interactive-html';
import { Markdown } from '../pi-chat-markdown/markdown';
import { Shimmer } from '../pi-chat/shimmer';
import type { ChatArtifactCardProps, ChatArtifactsConfig } from '../pi-chat/config';
import type { PmText } from './pm-text';

/**
 * Reads a file the PM presented (`present`, a `boring.artifact` descriptor) as text, at the descriptor's revision; undefined when it can't.
 * The one line reads it through the app's PM door (`{base}/resources`, see `use-improve-agent.ts`).
 */
export type PmReadArtifact = (artifact: ArtifactDescriptor, signal: AbortSignal) => Promise<string | undefined>;

type Loaded = { readonly text: string } | { readonly failed: true } | undefined;
interface Mockups { readonly read: PmReadArtifact | undefined; readonly text: PmText; readonly cache: Map<string, Promise<string | undefined>> }
const MockupContext = createContext<Mockups | null>(null);

/** The panel's presented files: the reader and its cache (one read per revision, shared by the thumbnail and the full view). */
export function PmMockupProvider({ read, text, children }: { readonly read: PmReadArtifact | undefined; readonly text: PmText; readonly children: ReactNode }) {
  const cache = useRef(new Map<string, Promise<string | undefined>>()).current;
  const value = useMemo(() => ({ read, text, cache }), [read, text, cache]);
  return <MockupContext.Provider value={value}>{children}</MockupContext.Provider>;
}

function useMockup(artifact: ArtifactDescriptor | undefined): Loaded {
  const context = useContext(MockupContext);
  const [loaded, setLoaded] = useState<{ readonly key: string; readonly value: Loaded }>();
  const key = artifact ? artifactVersionKey(artifact) : undefined;
  useEffect(() => {
    if (!artifact || !key || !context) return;
    const read = context.read;
    if (!read) { setLoaded({ key, value: { failed: true } }); return; }
    let pending = context.cache.get(key);
    if (!pending) {
      const abort = new AbortController();
      pending = read(artifact, abort.signal).catch(() => undefined);
      context.cache.set(key, pending);
      void pending.then(text => { if (text === undefined) context.cache.delete(key); });
    }
    let current = true;
    void pending.then(text => { if (current) setLoaded({ key, value: text === undefined ? { failed: true } : { text } }); });
    return () => { current = false; };
  }, [artifact, key, context]);
  return loaded && loaded.key === key ? loaded.value : undefined;
}

/** The mockup itself: HTML and SVG in a sandboxed frame (scripts only, opaque origin, no network), Markdown drawn, anything else as text. */
function MockupBody({ artifact, text, testId }: { readonly artifact: ArtifactDescriptor; readonly text: string; readonly testId: string }) {
  if (artifact.type === 'html' || artifact.type === 'svg') return <InteractiveFrame text={text} sources={[]} title={artifact.title} testId={testId} />;
  if (artifact.type === 'markdown') return <div data-testid={`${testId}-markdown`} className="min-h-0 flex-1 overflow-auto p-4 text-[15px]"><Markdown text={text} /></div>;
  return <pre data-testid={`${testId}-text`} className="m-0 min-h-0 flex-1 overflow-auto p-4 text-xs whitespace-pre-wrap">{text}</pre>;
}

const descriptorOf = (artifact: ChatArtifactCardProps['artifact']): ArtifactDescriptor | undefined => {
  const descriptor = artifact.state === 'ready' ? artifact.descriptor as PresentedArtifact : undefined;
  return descriptor && descriptor.type !== 'task' ? descriptor : undefined;
};

/**
 * A presented mockup in the member thread (C7): one row per mockup, so two or three presented in a row read as a vertical list. A small
 * live thumbnail (the sandboxed page at phone width, scaled down), the title and « Ouvrir › »; the whole row (min 64px) opens it full height.
 */
export function PmArtifactCard({ artifact, open, onOpen }: ChatArtifactCardProps) {
  const context = useContext(MockupContext);
  const descriptor = descriptorOf(artifact);
  const loaded = useMockup(descriptor);
  const title = descriptor?.title ?? artifact.title ?? '';
  return <div data-testid="pm-mockup" data-state={artifact.state} data-open={open ? 'true' : undefined} className="relative my-1 flex min-h-16 w-full max-w-sm items-center gap-3 rounded-pm-box border bg-background p-2">
    <div aria-hidden="true" inert className="relative h-24 w-16 shrink-0 overflow-hidden rounded-pm-control border bg-muted">
      {descriptor && loaded && 'text' in loaded && <div className="pointer-events-none absolute top-0 left-0 flex h-[585px] w-[390px] origin-top-left scale-[0.1641] flex-col">
        <MockupBody artifact={descriptor} text={loaded.text} testId="pm-mockup-thumb" />
      </div>}
    </div>
    <span className="flex min-w-0 flex-1 flex-col">
      <span data-testid="pm-mockup-title" className="truncate text-sm font-medium">{artifact.state === 'ready' ? title : <Shimmer>{title}</Shimmer>}</span>
      {loaded && 'failed' in loaded ? <span className="text-[13px] text-muted-foreground">{context?.text.mockupUnavailable}</span>
        : artifact.state === 'ready' && <span className="flex items-center text-[13px] text-muted-foreground">{context?.text.openMockup}<ChevronRightIcon className="size-3.5" aria-hidden="true" /></span>}
    </span>
    {descriptor && onOpen && <Button variant="link" data-testid="pm-mockup-open" aria-label={`${context?.text.openMockup ?? ''} ${title}`} onClick={onOpen} className="absolute inset-0 h-auto w-full" />}
  </div>;
}

/** The opened mockup, full height inside the sheet, under « ‹ Retour ». */
export function PmMockupView({ artifact, text, onBack }: { readonly artifact: ArtifactDescriptor; readonly text: PmText; readonly onBack: () => void }) {
  const loaded = useMockup(artifact);
  return <div data-testid="pm-mockup-view" className="flex min-h-0 flex-1 flex-col">
    <div className="flex shrink-0 items-center gap-1 py-1 pr-4 pl-2">
      <Button variant="ghost" data-testid="pm-mockup-back" onClick={onBack} className="min-h-11">{text.back}</Button>
      <span data-testid="pm-mockup-view-title" className="min-w-0 flex-1 truncate text-right text-[13px] text-muted-foreground">{artifact.title}</span>
    </div>
    {loaded && 'text' in loaded ? <MockupBody artifact={artifact} text={loaded.text} testId="pm-mockup-full" />
      : <p role="status" className="m-0 p-4 text-sm text-muted-foreground">{loaded ? text.mockupUnavailable : text.preparing}</p>}
  </div>;
}

/** The panel's artifacts config when the host gives none: `present` results become `PmArtifactCard`s that open in the sheet. */
export function pmArtifacts(open: (artifact: ArtifactDescriptor) => void, shown: ArtifactDescriptor | undefined): ChatArtifactsConfig {
  return {
    open: ((artifact: PresentedArtifact) => { if (artifact.type !== 'task') open(artifact); }) as ChatArtifactsConfig['open'],
    isOpen: ((artifact: PresentedArtifact) => shown !== undefined && artifact.type !== 'task' && artifactVersionKey(artifact) === artifactVersionKey(shown)) as NonNullable<ChatArtifactsConfig['isOpen']>,
    recognise: recogniseArtifact, Card: PmArtifactCard,
  };
}
